files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #e0e0e0;
  --pixel-border: 4px solid #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card);
  border: var(--pixel-border);
  box-shadow: 8px 8px 0 #0a0a1a;
  padding: 32px 24px;
  text-align: center;
  max-width: 400px;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--primary);
}

.mode-indicator {
  font-size: 1.25rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--secondary);
  background: var(--text);
  padding: 8px;
  border: 2px solid var(--primary);
}

.timer {
  font-size: clamp(3rem, 15vw, 5rem);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  letter-spacing: 4px;
  color: var(--text);
  line-height: 1.2;
  text-shadow: 4px 4px 0 var(--primary);
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  background: var(--secondary);
  color: var(--text);
  border: 3px solid var(--primary);
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  box-shadow: 4px 4px 0 #0a0a1a;
  transition: transform 0.1s, box-shadow 0.1s;
  font-family: inherit;
}

.btn:hover {
  background: var(--primary);
  color: var(--bg);
}

.btn:focus-visible {
  outline: 4px solid #ffffff;
  outline-offset: 2px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.mode-switch {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}

.mode-btn {
  padding: 8px 16px;
  font-size: 0.875rem;
}

.mode-btn.active {
  background: var(--primary);
  color: var(--bg);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .timer {
    font-size: clamp(2.5rem, 18vw, 4rem);
  }
  .btn {
    padding: 10px 16px;
    font-size: 0.875rem;
  }
}

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

let timeLeft = WORK_TIME;
let isRunning = false;
let timerInterval = null;
let currentMode = 'work';

const timerEl = document.getElementById('timer');
const startPauseBtn = document.getElementById('start-pause');
const resetBtn = document.getElementById('reset');
const modeIndicator = document.getElementById('mode-indicator');
const workModeBtn = document.getElementById('work-mode');
const breakModeBtn = document.getElementById('break-mode');

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function updateDisplay() {
  timerEl.textContent = formatTime(timeLeft);
}

function setMode(mode) {
  if (isRunning) return;
  currentMode = mode;
  timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
  modeIndicator.textContent = mode === 'work' ? 'Work' : 'Break';
  workModeBtn.classList.toggle('active', mode === 'work');
  breakModeBtn.classList.toggle('active', mode === 'break');
  workModeBtn.setAttribute('aria-pressed', mode === 'work');
  breakModeBtn.setAttribute('aria-pressed', mode === 'break');
  updateDisplay();
}

function startTimer() {
  if (isRunning) return;
  isRunning = true;
  startPauseBtn.textContent = 'Pause';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
  timerInterval = setInterval(() => {
    timeLeft--;
    updateDisplay();
    if (timeLeft <= 0) {
      clearInterval(timerInterval);
      isRunning = false;
      startPauseBtn.textContent = 'Start';
      startPauseBtn.setAttribute('aria-label', 'Start timer');
    }
  }, 1000);
}

function pauseTimer() {
  if (!isRunning) return;
  clearInterval(timerInterval);
  isRunning = false;
  startPauseBtn.textContent = 'Start';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function resetTimer() {
  clearInterval(timerInterval);
  isRunning = false;
  startPauseBtn.textContent = 'Start';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
  timeLeft = currentMode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
}

startPauseBtn.addEventListener('click', () => {
  if (isRunning) {
    pauseTimer();
  } else {
    startTimer();
  }
});

resetBtn.addEventListener('click', resetTimer);
workModeBtn.addEventListener('click', () => setMode('work'));
breakModeBtn.addEventListener('click', () => setMode('break'));

updateDisplay();
